// Writes packages/protocol/src/generated/index.ts re-exporting every generated module.
import { readdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const dir = join(import.meta.dirname, "..", "packages", "protocol", "src", "generated");
const names = readdirSync(dir)
  .filter((f) => f.endsWith(".ts") && f !== "index.ts")
  .map((f) => f.slice(0, -3))
  .sort();
const body =
  "// This file is generated by scripts/gen-protocol-index.mjs. Do not edit.\n" +
  names
    .map((n) =>
      n === "constants" ? `export * from "./${n}";\n` : `export type * from "./${n}";\n`,
    )
    .join("");
writeFileSync(join(dir, "index.ts"), body);
